import { isCanonicalNonEmptyString, validateNodeId } from "./validation.js";
import { INVALID_ARGUMENT } from "../../errors/index.js";
import { INTERNAL_DELAY_EVENT_NAME, INTERNAL_WAIT_KIND_FIELD } from "../timed-wait-state.js";
import { MAX_WORKFLOW_CHILD_RUN_DEPENDENCIES, MAX_WORKFLOW_CHILD_RUN_ID_CODE_UNITS, MAX_WORKFLOW_CHILD_RUN_NODE_ID_CODE_UNITS, } from "../limits.js";
/** Create a wait-for-approval node. Pauses until human approves/rejects. */
export function waitForApproval(id, options = {}) {
    validateNodeId(id);
    return {
        id,
        config: {
            type: "wait",
            description: options.description,
            waitType: "approval",
            message: options.message ?? "Approval required",
            payload: options.payload,
            approvers: options.approvers,
            ...(options.responseSchema ? { responseSchema: options.responseSchema } : {}),
            timeout: options.timeout,
            checkpoint: true,
            retry: options.retry,
            skip: options.skip,
        },
    };
}
/** Pause until the control plane observes every referenced child run as terminal. */
export function waitForRuns(id, options) {
    validateNodeId(id);
    if (id.length > MAX_WORKFLOW_CHILD_RUN_NODE_ID_CODE_UNITS) {
        throw INVALID_ARGUMENT.create({ detail: `waitForRuns node id must be at most 255 code units` });
    }
    if (Array.isArray(options.runIds))
        validateChildRunIds(id, options.runIds);
    return {
        id,
        config: {
            type: "wait",
            description: options.description,
            waitType: "child_run",
            runIds: options.runIds,
            checkpoint: true,
            retry: options.retry,
            skip: options.skip,
        },
    };
}
function validateChildRunIds(id, runIds) {
    if (runIds.length === 0 || runIds.length > MAX_WORKFLOW_CHILD_RUN_DEPENDENCIES ||
        runIds.some((runId) => !isCanonicalNonEmptyString(runId) ||
            runId.length > MAX_WORKFLOW_CHILD_RUN_ID_CODE_UNITS || !/^[a-zA-Z0-9_-]+$/.test(runId))) {
        throw INVALID_ARGUMENT.create({
            detail: `waitForRuns "${id}" requires 1 to 1000 run ids matching ` +
                `[a-zA-Z0-9_-]+ with at most 128 code units`,
        });
    }
}
/** Create a wait-for-event node. Pauses until external event is received. */
export function waitForEvent(id, options) {
    validateNodeId(id);
    if (!isCanonicalNonEmptyString(options.eventName)) {
        throw INVALID_ARGUMENT.create({ detail: `waitForEvent "${id}" must specify an eventName` });
    }
    // The reserved delay transport name would make this wait indistinguishable
    // from a delay(): the runtime would never release it through a published
    // event, and its timeout would complete the node instead of failing the run.
    if (options.eventName === INTERNAL_DELAY_EVENT_NAME) {
        throw INVALID_ARGUMENT.create({
            detail: `waitForEvent "${id}" cannot use the reserved event name ` +
                `"${INTERNAL_DELAY_EVENT_NAME}"; use delay() for a timed pause`,
        });
    }
    return {
        id,
        config: {
            type: "wait",
            description: options.description,
            waitType: "event",
            eventName: options.eventName,
            timeout: options.timeout,
            checkpoint: true,
            retry: options.retry,
            skip: options.skip,
        },
    };
}
/** Create a simple delay/sleep node. */
export function delay(id, duration) {
    validateNodeId(id);
    return {
        id,
        config: {
            type: "wait",
            waitType: "event",
            eventName: INTERNAL_DELAY_EVENT_NAME,
            timeout: duration,
            checkpoint: false,
            // Explicit marker, so a delay stays a delay through definition capture
            // and persistence without leaning on the reserved-name fallback.
            [INTERNAL_WAIT_KIND_FIELD]: "delay",
        },
    };
}
